CREATE TABLE pillars (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL
);

CREATE TABLE guides (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  pillar_id TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (pillar_id) REFERENCES pillars(id)
);
